@extends('layouts.hris')
@section('title', 'Overtime & COC')
@section('subtitle', 'Authorize overtime separately from measured attendance and compensatory credits.')
@section('actions')<button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#ot-modal">Request overtime</button>@endsection
@section('content')
<div class="alert alert-info">Approval authorizes overtime. It does not create rendered hours or COC automatically; those rules await an approved HR policy.</div>
<x-hris.table id="ot-table" endpoint="/overtime/data" search filters :columns="[['key'=>'employee.name','label'=>'Employee'],['key'=>'dates_label','label'=>'Dates'],['key'=>'hours','label'=>'Requested hours'],['key'=>'type_label','label'=>'Treatment'],['key'=>'current_status','label'=>'Status']]" :actions="[['name'=>'details','label'=>'Details'],['name'=>'review','label'=>'Review / cancel']]"/>
<x-hris.modal id="ot-modal" title="Request overtime"><form id="ot-form" data-endpoint="/overtime" enctype="multipart/form-data"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none" tabindex="-1"></div><div class="row g-3"><x-hris.field name="dates_text" label="Dates (one YYYY-MM-DD per line)" type="textarea" required class="col-12"/><x-hris.field name="day_type" type="select" :options="[1=>'Saturday / Sunday',2=>'Legal holiday',3=>'Declared non-working holiday']" required/><x-hris.field name="overtime_type" type="select" :options="[1=>'With overtime pay',2=>'Without overtime pay',3=>'With compensatory time off']" required/><x-hris.field name="start_time" type="time" required/><x-hris.field name="requested_minutes" label="Requested minutes" type="number" required min="1" max="1440"/><x-hris.field name="purpose" type="textarea" required class="col-12"/><x-hris.field name="attachment" label="Authorization evidence (PDF/JPG/PNG, optional)" type="file" accept=".pdf,.jpg,.jpeg,.png" class="col-12"/></div></div><div class="modal-footer"><button class="btn btn-primary">File authorization</button></div></form></x-hris.modal>
<x-hris.modal id="ot-action" title="Review overtime"><form id="ot-action-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none" tabindex="-1"></div><x-hris.field name="action" type="select" :options="['approve_dc'=>'Recommend as division chief','reject_dc'=>'Disapprove as division chief','approve_ed'=>'Approve as ED/OIC','reject_ed'=>'Disapprove as ED/OIC','cancel'=>'Cancel my request']" required class="col-12"/><x-hris.field name="reason" type="textarea" class="col-12"/></div><div class="modal-footer"><button class="btn btn-primary">Submit decision</button></div></form></x-hris.modal>
@endsection
@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#ot-table'),form=document.querySelector('#ot-form'),action=document.querySelector('#ot-action-form');HRIS.bindForm(form,{prepare:b=>{const dates=String(b.get('dates_text')||'').split(/\s+/).filter(Boolean);b.delete('dates_text');dates.forEach((date,index)=>b.append(`dates[${index}]`,date))},success:()=>table.table.load()});HRIS.bindForm(action,{success:()=>table.table.load()});table.addEventListener('table:action',({detail:{action:kind,row}})=>{if(kind==='details')HRIS.showDetails('Overtime authorization',row);else{HRIS.fillForm(action,{});action.dataset.endpoint=`/overtime/${row.id}/transition`;HRIS.openModal('ot-action')}})});</script>@endpush
